const FILTER_HOTKEYS: [&str; 5] =
    ["Filter: Unread", "Filter: Drafts", "Filter: Unanswered", "Filter: DMs", "Filter: Groups"];
/// The hotkeys that act on the sign-in window and before sign-in. Desktop binds all hotkeys there, but the others act
/// on chats and on the command bar, which Desktop does not draw before the onboarding ends.
const SIGN_IN_HOTKEYS: [&str; 10] = [
    "Minimize To Tray",
    "Quit App",
    "Reload App",
    "Report a Problem",
    "Reset Zoom",
    "Settings",
    "Toggle Sidebar",
    "Toggle Space Bar",
    "Zoom In",
    "Zoom Out",
];
const F_ARCHIVED: usize = 5;
const F_REQUESTS: usize = 6;
const F_LOW_PRIORITY: usize = 7;

/// Desktop's membership events, which the timeline groups.
fn membership(m: &Message) -> bool {
    m.message_type.as_deref() == Some("MEMBERSHIP")
}

/// Composer content with `text` and the cursor at the end.
fn composer_with(text: &str) -> text_editor::Content {
    format::content(text, text.len()..text.len())
}

/// Desktop's `getComposerUnavailableNotice`: the reason that the chat has no composer, under the last message. An
/// upgraded chat whose new room is in the list shows a link in place of the composer.
fn unavailable(st: &BeeperStore, chat: &Chat) -> Option<&'static str> {
    match &chat.replacement_room {
        Some(room) => st.resolve_chat_idx(room).is_none().then_some("Chat was upgraded."),
        None => chat.is_read_only.then_some("Messaging isn't available in this chat"),
    }
}

fn filter_hit(i: usize, c: &Chat, st: &BeeperStore) -> bool {
    match i {
        0 => c.flags & CHAT_UNREAD != 0,
        1 => c.draft.is_some(),
        2 => {
            let v = st.chat_msg_indices.get(&c.id);
            v.and_then(|v| v.iter().rev().map(|&i| &st.messages[i]).find(|m| !m.silent())).is_none_or(|m| {
                m.is_sender != Some(true) && !m.reactions.iter().any(|r| r.participant_id == st.me().id)
            })
        }
        3 => c.chat_type != "group",
        4 => c.chat_type == "group",
        F_ARCHIVED => c.flags & CHAT_ARCHIVED != 0,
        F_REQUESTS => c.flags & CHAT_REQUEST != 0,
        F_LOW_PRIORITY => c.flags & CHAT_LOW_PRIORITY != 0,
        _ => unreachable!("filter index {i}"),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SettingsTab {
    Profile,
    Accounts,
    General,
    Appearance,
    Notifications,
    Hotkeys,
    Devices,
    Ai,
    BeeperPlus,
    Integrations,
    Storage,
    Help,
    About,
}

#[derive(Clone, Copy)]
pub enum TabIcon {
    /// The avatar of the Beeper account.
    Avatar,
    Glyph(char),
    Svg(&'static [u8]),
}

impl SettingsTab {
    pub const ALL: [Self; 13] = [
        Self::Profile,
        Self::Accounts,
        Self::General,
        Self::Appearance,
        Self::Notifications,
        Self::Hotkeys,
        Self::Devices,
        Self::Ai,
        Self::BeeperPlus,
        Self::Integrations,
        Self::Storage,
        Self::Help,
        Self::About,
    ];

    /// Desktop's nav items: Beeper Plus shows only when the account can subscribe.
    pub fn listed(st: &BeeperStore) -> impl Iterator<Item = Self> {
        let plus = st.whoami.can_subscribe;
        Self::ALL.into_iter().filter(move |t| *t != Self::BeeperPlus || plus)
    }

    /// The translated name of the section.
    pub fn name(self) -> &'static str {
        tr(self.meta().0)
    }

    /// Desktop's `searchKeywords` of the section.
    pub fn keywords(self) -> &'static [&'static str] {
        match self {
            Self::Profile => &["recovery code", "show recovery key", "backup key", "encryption key"],
            Self::Integrations => &[
                "beeper desktop api",
                "mcp",
                "openapi",
                "access token",
                "approved connections",
                "remote access",
                "claude",
                "raycast",
                "cursor",
                "codex",
            ],
            _ => &[],
        }
    }

    /// Desktop's `.account-pref-pane` gives the Accounts, Devices and Storage panes `--appearance-color-bg-primary`.
    pub fn pane(self, p: &Palette) -> Color {
        match self {
            Self::Accounts | Self::Devices | Self::Storage => p.card,
            _ => p.prefs_pane,
        }
    }

    /// The name, the icon, and the token of the icon tile color.
    pub fn meta(self) -> (&'static str, TabIcon, Token) {
        use TabIcon::{Glyph, Svg};
        let tabs: [(_, _, Token); 13] = [
            ("Profile", TabIcon::Avatar, |_| CLEAR),
            ("Accounts", Glyph(icon::AT_SIGN), |_| hex(0x9745ea)),
            ("General", Svg(include_bytes!("../assets/settings/general.svg")), |_| hex(0x0eb3ef)),
            ("Appearance", Svg(include_bytes!("../assets/settings/appearance.svg")), |_| hex(0xd833ca)),
            ("Notifications", Svg(include_bytes!("../assets/settings/notifications.svg")), |_| hex(0x19ba3b)),
            ("Hotkeys", Svg(include_bytes!("../assets/settings/hotkeys.svg")), |_| hex(0xebaa00)),
            ("Devices", Svg(include_bytes!("../assets/settings/devices.svg")), |_| hex(0xf54c03)),
            ("AI", Svg(include_bytes!("../assets/settings/ai.svg")), |_| hex(0x19c9d4)),
            ("Beeper Plus", Svg(include_bytes!("../assets/settings/beeper_plus.svg")), |p| p.accent),
            ("Integrations", Glyph(icon::PUZZLE), |_| hex(0x7559ff)),
            ("Storage", Glyph(icon::DATABASE), |_| hex(0x32546a)),
            ("Help", Svg(include_bytes!("../assets/settings/help.svg")), |p| p.on_secondary),
            ("About", Svg(include_bytes!("../assets/settings/about.svg")), |_| hex(0x1ab5a2)),
        ];
        tabs[self as usize]
    }
}

